changes.detail:
Defaults in v3.0.0:
minio.address = null  # Allow the address used by Loki to refer to Minio to be overridden
minio.persistence.annotations = {}

"{{- if .Values.enterprise.adminApi.enabled }}
{{- if or .Values.minio.enabled (eq .Values.loki.storage.type "s3") (eq .Values.loki.storage.type "gcs") (eq .Values.loki.storage.type "azure") }}
admin_client:
  storage:
    s3:
      bucket_name: {{ .Values.loki.storage.bucketNames.admin }}
{{- end }}
{{- end }}
auth:
  type: {{ .Values.enterprise.adminApi.enabled | ternary "enterprise" "trust" }}
auth_enabled: {{ .Values.loki.auth_enabled }}
cluster_name: {{ include "loki.clusterName" . }}
license:
  path: /etc/loki/license/license.jwt
" → "{{- if .Values.enterprise.adminApi.enabled }}
admin_client:
  {{ include "enterprise-logs.adminAPIStorageConfig" . | nindent 2 }}
{{ end }}
auth:
  type: {{ .Values.enterprise.adminApi.enabled | ternary "enterprise" "trust" }}
auth_enabled: {{ .Values.loki.auth_enabled }}
cluster_name: {{ include "loki.clusterName" . }}
license:
  path: /etc/loki/license/license.jwt
"

"{{- if .Values.enterprise.enabled}}
{{- tpl .Values.enterprise.config . }}
{{- else }}
auth_enabled: {{ .Values.loki.auth_enabled }}
{{- end }}

{{- with .Values.loki.server }}
server:
  {{- toYaml . | nindent 2}}
{{- end}}

memberlist:
{{- if .Values.loki.memberlistConfig }}
  {{- toYaml .Values.loki.memberlistConfig | nindent 2 }}
{{- else }}
{{- if .Values.loki.extraMemberlistConfig}}
{{- toYaml .Values.loki.extraMemberlistConfig | nindent 2}}
{{- end }}
  join_members:
    - {{ include "loki.memberlist" . }}
    {{- with .Values.migrate.fromDistributed }}
    {{- if .enabled }}
    - {{ .memberlistService }}
    {{- end }}
    {{- end }}
{{- end }}

{{- with .Values.loki.ingester }}
ingester:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- if .Values.loki.commonConfig}}
common:
{{- toYaml .Values.loki.commonConfig | nindent 2}}
  storage:
  {{- include "loki.commonStorageConfig" . | nindent 4}}
{{- end}}

{{- with .Values.loki.limits_config }}
limits_config:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

runtime_config:
  file: /etc/loki/runtime-config/runtime-config.yaml

{{- with .Values.loki.memcached.chunk_cache }}
{{- if and .enabled (or .host .addresses) }}
chunk_store_config:
  chunk_cache_config:
    memcached:
      batch_size: {{ .batch_size }}
      parallelism: {{ .parallelism }}
    memcached_client:
      {{- if .host }}
      host: {{ .host }}
      {{- end }}
      {{- if .addresses }}
      addresses: {{ .addresses }}
      {{- end }}
      service: {{ .service }}
{{- end }}
{{- end }}

{{- if .Values.loki.schemaConfig }}
schema_config:
{{- toYaml .Values.loki.schemaConfig | nindent 2}}
{{- else }}
schema_config:
  configs:
    - from: 2022-01-11
      store: boltdb-shipper
      object_store: {{ .Values.loki.storage.type }}
      schema: v12
      index:
        prefix: loki_index_
        period: 24h
{{- end }}

{{ include "loki.rulerConfig" . }}

{{- if or .Values.tableManager.retention_deletes_enabled .Values.tableManager.retention_period }}
table_manager:
  retention_deletes_enabled: {{ .Values.tableManager.retention_deletes_enabled }}
  retention_period: {{ .Values.tableManager.retention_period }}
{{- end }}

{{- with .Values.loki.memcached.results_cache }}
query_range:
  align_queries_with_step: true
  {{- if and .enabled (or .host .addresses) }}
  cache_results: {{ .enabled }}
  results_cache:
    cache:
      default_validity: {{ .default_validity }}
      memcached_client:
        {{- if .host }}
        host: {{ .host }}
        {{- end }}
        {{- if .addresses }}
        addresses: {{ .addresses }}
        {{- end }}
        service: {{ .service }}
        timeout: {{ .timeout }}
  {{- end }}
{{- end }}

{{- with .Values.loki.storage_config }}
storage_config:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.query_scheduler }}
query_scheduler:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.compactor }}
compactor:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.analytics }}
analytics:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.querier }}
querier:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.index_gateway }}
index_gateway:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.frontend }}
frontend:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.frontend_worker }}
frontend_worker:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.distributor }}
distributor:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

tracing:
  enabled: {{ .Values.loki.tracing.enabled }}
" → "{{- if .Values.enterprise.enabled}}
{{- tpl .Values.enterprise.config . }}
{{- else }}
auth_enabled: {{ .Values.loki.auth_enabled }}
{{- end }}

{{- with .Values.loki.server }}
server:
  {{- toYaml . | nindent 2}}
{{- end}}

pattern_ingester:
  enabled: {{ .Values.loki.pattern_ingester.enabled }}

memberlist:
{{- if .Values.loki.memberlistConfig }}
  {{- toYaml .Values.loki.memberlistConfig | nindent 2 }}
{{- else }}
{{- if .Values.loki.extraMemberlistConfig}}
{{- toYaml .Values.loki.extraMemberlistConfig | nindent 2}}
{{- end }}
  join_members:
    - {{ include "loki.memberlist" . }}
    {{- with .Values.migrate.fromDistributed }}
    {{- if .enabled }}
    - {{ .memberlistService }}
    {{- end }}
    {{- end }}
{{- end }}

{{- with .Values.loki.ingester }}
ingester:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- if .Values.loki.commonConfig}}
common:
{{- toYaml .Values.loki.commonConfig | nindent 2}}
  storage:
  {{- include "loki.commonStorageConfig" . | nindent 4}}
{{- end}}

{{- with .Values.loki.limits_config }}
limits_config:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

runtime_config:
  file: /etc/loki/runtime-config/runtime-config.yaml

{{- with .Values.chunksCache }}
{{- if .enabled }}
chunk_store_config:
  chunk_cache_config:
    default_validity: {{ .defaultValidity }}
    background:
      writeback_goroutines: {{ .writebackParallelism }}
      writeback_buffer: {{ .writebackBuffer }}
      writeback_size_limit: {{ .writebackSizeLimit }}
    memcached:
      batch_size: {{ .batchSize }}
      parallelism: {{ .parallelism }}
    memcached_client:
      addresses: dnssrvnoa+_memcached-client._tcp.{{ template "loki.fullname" $ }}-chunks-cache.{{ $.Release.Namespace }}.svc
      consistent_hash: true
      timeout: {{ .timeout }}
      max_idle_conns: 72
{{- end }}
{{- end }}

{{- if .Values.loki.schemaConfig }}
schema_config:
{{- toYaml .Values.loki.schemaConfig | nindent 2}}
{{- end }}

{{- if .Values.loki.useTestSchema }}
schema_config:
{{- toYaml .Values.loki.testSchemaConfig | nindent 2}}
{{- end }}

{{ include "loki.rulerConfig" . }}

{{- if or .Values.tableManager.retention_deletes_enabled .Values.tableManager.retention_period }}
table_manager:
  retention_deletes_enabled: {{ .Values.tableManager.retention_deletes_enabled }}
  retention_period: {{ .Values.tableManager.retention_period }}
{{- end }}

query_range:
  align_queries_with_step: true
  {{- with .Values.loki.query_range }}
  {{- tpl (. | toYaml) $ | nindent 2 }}
  {{- end }}
  {{- if .Values.resultsCache.enabled }}
  {{- with .Values.resultsCache }}
  cache_results: true
  results_cache:
    cache:
      default_validity: {{ .defaultValidity }}
      background:
        writeback_goroutines: {{ .writebackParallelism }}
        writeback_buffer: {{ .writebackBuffer }}
        writeback_size_limit: {{ .writebackSizeLimit }}
      memcached_client:
        consistent_hash: true
        addresses: dnssrvnoa+_memcached-client._tcp.{{ template "loki.fullname" $ }}-results-cache.{{ $.Release.Namespace }}.svc
        timeout: {{ .timeout }}
        update_interval: 1m
  {{- end }}
  {{- end }}

{{- with .Values.loki.storage_config }}
storage_config:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.query_scheduler }}
query_scheduler:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.compactor }}
compactor:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.analytics }}
analytics:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.querier }}
querier:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.index_gateway }}
index_gateway:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.frontend }}
frontend:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.frontend_worker }}
frontend_worker:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

{{- with .Values.loki.distributor }}
distributor:
  {{- tpl (. | toYaml) $ | nindent 4 }}
{{- end }}

tracing:
  enabled: {{ .Values.loki.tracing.enabled }}
"
